pou.interface:
{implicit on}
{attribute 'hide'}
{attribute 'qualified_only'}
{attribute 'linkalways'}

FUNCTION __CheckedInterfaceAssign : __XWORD
VAR_INPUT
InterfaceInput : __XWORD;
correction : DINT;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
IF (InterfaceInput = 0) THEN
	__CheckedInterfaceAssign := 0;
ELSE
	__CheckedInterfaceAssign := InterfaceInput + correction;
END_IF
{implicit off}
